#!/usr/bin/env node
// Builds the committed vendor bundle.
//
// Why a bundle rather than a committed node_modules tree: the tree's deepest path was 187
// characters, and with a workspace prefix that exceeds Windows' 260-character MAX_PATH, so
// `git checkout` failed outright on Windows - for CI and for any user cloning the repository.
// A nested node_modules was also silently excluded by the `node_modules/` gitignore rule, which
// left the committed tree one package short of its own lockfile.
//
// This is a MAINTAINER step. It needs the network. Run it after changing scripts/vendor/package.json:
//   node scripts/build-vendor-bundle.mjs
// then commit the bundle, VERSIONS.json, BUNDLE.sha256, SBOM.json and LICENSES.md.

import { createHash } from 'node:crypto';
import { execFileSync } from 'node:child_process';
import { readFileSync, writeFileSync, existsSync, mkdirSync, rmSync, readdirSync, statSync } from 'node:fs';
import { join, dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const repoRoot = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const vendorDir = join(
  repoRoot,
  'plugins/bruno-gen-collection/skills/bruno-collection-generator/scripts/vendor',
);
const modulesDir = join(vendorDir, 'node_modules');
const ESBUILD = 'esbuild@0.28.1'; // pinned: the bundle must be reproducible

// shell: true is required on Windows, where npm/npx are .cmd shims that Node refuses to spawn
// directly. Every argument here is a literal from this file, never user input.
const sh = (cmd, args, cwd) =>
  execFileSync(cmd, args, {
    cwd,
    encoding: 'utf8',
    stdio: ['ignore', 'pipe', 'pipe'],
    shell: process.platform === 'win32',
  });

const npm = 'npm';
const npx = 'npx';

// ---- 1. install the pinned dependencies (never committed) ------------------------------------
console.log('installing pinned dependencies...');
sh(npm, ['ci', '--omit=dev', '--ignore-scripts', '--no-audit', '--no-fund'], vendorDir);

// ---- 2. record the versions, since the bundle has no package.json files ---------------------
const packageVersion = (name) =>
  JSON.parse(readFileSync(join(modulesDir, ...name.split('/'), 'package.json'), 'utf8')).version;

const versions = {
  note: 'Generated by scripts/build-vendor-bundle.mjs. The bundle has no package.json files, so versions are recorded here.',
  filestore: packageVersion('@usebruno/filestore'),
  lang: packageVersion('@usebruno/lang'),
  converters: packageVersion('@usebruno/converters'),
  schema: packageVersion('@usebruno/schema'),
  ajv: packageVersion('ajv'),
  yaml: packageVersion('yaml'),
};

// ---- 3. bundle ------------------------------------------------------------------------------
// One CJS bundle. CJS, not ESM, because filestore locates its worker script with __dirname,
// which does not exist in an ESM bundle - the objection that ruled bundling out earlier applied
// to the ESM build only.
const entry = join(vendorDir, '.bundle-entry.cjs');
writeFileSync(
  entry,
  [
    '// Generated entry point. Do not commit.',
    "const filestore = require('@usebruno/filestore');",
    "const converters = require('@usebruno/converters');",
    "const lang = require('@usebruno/lang');",
    "const Ajv2020 = require('ajv/dist/2020.js');",
    "const YAML = require('yaml');",
    'module.exports = { filestore, converters, lang, Ajv2020, YAML };',
    '',
  ].join('\n'),
);

const bundlePath = join(vendorDir, 'bruno-libs.cjs');
console.log('bundling...');
sh(
  npx,
  [
    '--yes', ESBUILD, entry,
    '--bundle',
    '--platform=node',
    '--format=cjs',
    '--target=node20',
    '--legal-comments=none',
    `--outfile=${bundlePath}`,
  ],
  vendorDir,
);

// The worker script is resolved lazily via join(__dirname, './workers/worker-script.js'), so it
// must sit beside the bundle. We never call the *ViaWorker functions, but a missing file would
// turn a future call into a confusing crash rather than a clear one.
const workerSrc = join(modulesDir, '@usebruno/filestore/dist/cjs/workers/worker-script.js');
const workerOut = join(vendorDir, 'workers', 'worker-script.js');
if (existsSync(workerSrc)) {
  mkdirSync(dirname(workerOut), { recursive: true });
  sh(
    npx,
    ['--yes', ESBUILD, workerSrc, '--bundle', '--platform=node', '--format=cjs', '--target=node20',
      '--legal-comments=none', `--outfile=${workerOut}`],
    vendorDir,
  );
  console.log(`  worker: ${(statSync(workerOut).size / 1024).toFixed(0)} KB`);
}

rmSync(entry, { force: true });

// ---- 4. SBOM and licence notices, from the installed tree ------------------------------------
const LICENSE_FILE = /^(LICENSE|LICENCE|COPYING)(\.\w+)?$/i;
const packages = [];
const walk = (root) => {
  for (const entryName of readdirSync(root).sort()) {
    if (entryName === '.bin' || entryName === '.package-lock.json') continue;
    const dir = join(root, entryName);
    if (!statSync(dir).isDirectory()) continue;
    if (entryName.startsWith('@')) {
      for (const scoped of readdirSync(dir).sort()) collect(join(dir, scoped));
    } else {
      collect(dir);
    }
  }
};
const collect = (dir) => {
  const manifest = join(dir, 'package.json');
  if (existsSync(manifest)) {
    const m = JSON.parse(readFileSync(manifest, 'utf8'));
    let license = m.license ?? null;
    if (license && typeof license === 'object') license = license.type ?? null;
    if (!license && Array.isArray(m.licenses)) license = m.licenses.map((l) => l.type).join(' OR ');
    packages.push({
      name: m.name ?? null,
      version: m.version ?? null,
      license: license ?? 'UNKNOWN',
      licenseFile: readdirSync(dir).find((f) => LICENSE_FILE.test(f)) ?? null,
    });
  }
  const nested = join(dir, 'node_modules');
  if (existsSync(nested)) walk(nested);
};
walk(modulesDir);
// Code point, not locale: the SBOM this produces is committed and its digest is verified by
// check-vendor-hash, so an ordering that depends on the machine's locale would fail the check
// somewhere else rather than here.
packages.sort((a, b) => {
  const x = `${a.name}@${a.version}`;
  const y = `${b.name}@${b.version}`;
  return x < y ? -1 : x > y ? 1 : 0;
});

const byLicence = {};
for (const p of packages) (byLicence[p.license] ??= []).push(`${p.name}@${p.version}`);
const unlicensed = packages.filter((p) => p.license === 'UNKNOWN');

const bundleBytes = readFileSync(bundlePath);
const bundleHash = createHash('sha256').update(bundleBytes).digest('hex');

writeFileSync(join(vendorDir, 'VERSIONS.json'), `${JSON.stringify(versions, null, 2)}\n`);
writeFileSync(join(vendorDir, 'BUNDLE.sha256'), `${bundleHash}  bruno-libs.cjs\n`);
writeFileSync(
  join(vendorDir, 'SBOM.json'),
  `${JSON.stringify(
    {
      note: 'Generated by scripts/build-vendor-bundle.mjs. Do not edit by hand.',
      bundle: 'bruno-libs.cjs',
      bundleSha256: bundleHash,
      bundleBytes: bundleBytes.length,
      directDependencies: JSON.parse(readFileSync(join(vendorDir, 'package.json'), 'utf8')).dependencies,
      versions,
      packageCount: packages.length,
      licenseSummary: Object.fromEntries(
        Object.entries(byLicence).sort((a, b) => b[1].length - a[1].length).map(([k, v]) => [k, v.length]),
      ),
      packages,
    },
    null,
    2,
  )}\n`,
);

writeFileSync(
  join(vendorDir, 'LICENSES.md'),
  `${[
    '# Third-party licence notices',
    '',
    'The committed bundle `bruno-libs.cjs` contains the third-party code listed below.',
    'Generated by `scripts/build-vendor-bundle.mjs` - do not edit by hand.',
    '',
    `Bundle: **${(bundleBytes.length / 1024 / 1024).toFixed(2)} MB**, sha256 \`${bundleHash}\`.`,
    `Packages bundled: **${packages.length}**.`,
    '',
    '## Licences in use',
    '',
    '| Licence | Packages |',
    '|---|---|',
    ...Object.entries(byLicence)
      .sort((a, b) => b[1].length - a[1].length)
      .map(([lic, list]) => `| ${lic} | ${list.length} |`),
    '',
    unlicensed.length
      ? `> **${unlicensed.length} package(s) declare no licence**: ${unlicensed.map((p) => `\`${p.name}@${p.version}\``).join(', ')}.`
      : '> Every bundled package declares a licence.',
    '',
    '## Full inventory',
    '',
    '| Package | Version | Licence |',
    '|---|---|---|',
    ...packages.map((p) => `| ${p.name} | ${p.version} | ${p.license} |`),
    '',
  ].join('\n')}`,
);

console.log(`\nbundle:   ${(bundleBytes.length / 1024 / 1024).toFixed(2)} MB`);
console.log(`sha256:   ${bundleHash}`);
console.log(`packages: ${packages.length} (${Object.keys(byLicence).length} distinct licences)`);
console.log(`versions: ${Object.entries(versions).filter(([k]) => k !== 'note').map(([k, v]) => `${k}@${v}`).join(', ')}`);
if (unlicensed.length) console.log(`WARNING: ${unlicensed.length} package(s) declare no licence`);
console.log('\nCommit: bruno-libs.cjs, workers/worker-script.js, VERSIONS.json, BUNDLE.sha256, SBOM.json, LICENSES.md');
